type Cache[K comparable, V any] struct {
    mu sync.RWMutex
    m  map[K]entry[V]
    sf singleflight.Group
}

func (c *Cache[K, V]) Get(ctx context.Context, k K) (V, error) {
    if v, ok := c.load(k); ok { return v, nil }          // cache hit
    res, err, _ := c.sf.Do(fmt.Sprint(k), func() (any, error) {
        if v, ok := c.load(k); ok { return v, nil }      // re-check: another goroutine filled it
        v, err := c.source.Read(ctx, k)                  // source of truth
        if err == nil { c.store(k, v, c.ttl) }
        return v, err
    })
    if err != nil { var zero V; return zero, err }
    return res.(V), nil
}
// write: c.source.Write(ctx, k, v); c.mu.Lock(); delete(c.m, k); c.mu.Unlock()

