func (c *Repo) Get(ctx context.Context, id string) (*Entity, error) {
    if b, err := c.rdb.Get(ctx, key(id)).Bytes(); err == nil { return decode(b) } // hit
    v, err, _ := c.sf.Do(key(id), func() (any, error) {
        e, err := c.store.Find(ctx, id)              // source of truth
        if err != nil { return nil, err }
        c.rdb.Set(ctx, key(id), encode(e), c.ttl)    // populate with TTL
        return e, nil
    })
    if err != nil { return nil, err }
    return v.(*Entity), nil
}
